questionvariables.text:
/*Defining the question variables*/ 
coef_w:1; /*coefficient of w*/
const1: rand([4,25,16,36,49,64,81,9,100]); /*constant in the function*/
func:(coef_w*w)/(const1-(coef_w*w^2))^(1/3);
aa:(((coef_w*w)/(2*coef_w*w))*u^(-1/3));
bb:int(aa,u);
cc:bb/u^(2/3);
w_pt: sqrt(const1/coef_w);
lower_limit: rand(2);



/*Model answer*/
expr_1:coef_w*w^(2)-const1;
diff_u: diff(expr_1,w);
func_1: func*(1/diff_u);
func_2: subst(u,expr_1,func_1);
expr_2:subst(t,w,expr_1);
expr_3:ev(expr_2,t=lower_limit);
func_3: int(func_2,u);

lower_limit_u: ev(expr_1,w=lower_limit);
upper_limit_u: ev(expr_1,w=t);

func_4: ev(func_3,u=upper_limit_u)-ev(func_3,u=lower_limit_u);
func_5: ratsimp(func_4);
expr_t:cc*(coef_w*w^(2)-const1)^(2/3);
expr_t1:subst(t,w,expr_t);
expr_t2:subst(1,w,expr_t);
model_expr:-cc*(expr_3)^(2/3);
model1_expr:ev(model_expr);
ta_2:  limit(func_5,t,w_pt); /*model ans part (a)*/
ta_2_a: limit(model_expr,t,w_pt);
ta_2_b: ratsimp(ta_2_a);
ta_3: random_permutation([["convergent", true],["divergent", false],["convergent and divergent", false]]);

feedbackvariables.text:
/*node 1:checks for correct answers*/

/*node 2:Integrating the indefinite integral without the limits.*/
mistake_2:int(func,w);
/*node 3:Interchanging the limits of integration, however, with the correct definite integral*/
mistake_3:int(func,w);
